package netcheck

import (
	"context"
	"net"
	"net/url"
	"strconv"

	"github.com/anthnel/devdesk/internal/netproxy"
)

// runProxy says whether a proxy variable applies to the target. It observes,
// it does not test: nothing is sent to the proxy, nothing is sent anywhere, and
// the checks around it stay direct.
//
// The scheme the HEAD will speak depends on a handshake that runs later, so the
// stage asks about both, https first, and merges the answers.
func runProxy(_ context.Context, t Target, env Env, _ Settings, _ *Results) []Check {
	host := net.JoinHostPort(t.Host, strconv.Itoa(t.Port))
	https := env.ProxyFor(&url.URL{Scheme: "https", Host: host})
	http := env.ProxyFor(&url.URL{Scheme: "http", Host: host})

	c := newCheck(CheckProxy, StageProxy, NotApplicable, "")
	c.fact("HTTPS", describeDecision(https))
	c.fact("HTTP", describeDecision(http))

	// A proxy is configured as soon as one scheme is proxied, even when the other
	// scheme's variable is invalid and the merged verdict says so.
	c.Proxy = proxyShown(https, http)

	switch {
	case https.Kind == netproxy.DecisionInvalid || http.Kind == netproxy.DecisionInvalid:
		c.Verdict, c.Reason = Warn, ReasonProxyInvalid
		c.Summary = invalidSummary(https, http)
	case https.Kind == netproxy.DecisionProxied || http.Kind == netproxy.DecisionProxied:
		c.Verdict, c.Reason = Info, ReasonProxyConfigured
		c.Summary = "Configured for this target: " + proxiedSummary(https, http)
	case https.Kind == netproxy.DecisionExcluded || http.Kind == netproxy.DecisionExcluded:
		c.Reason, c.Summary = ReasonProxyExcluded, "Excluded by NO_PROXY"
	case https.Kind == netproxy.DecisionLoopback || http.Kind == netproxy.DecisionLoopback:
		c.Reason, c.Summary = ReasonProxyLoopback, "Not used for a loopback target"
	default:
		c.Reason, c.Summary = ReasonProxyNone, "None"
	}
	return []Check{c}
}

// proxyShown is the proxy a proxied scheme goes through, https first, and empty
// when neither scheme is proxied.
func proxyShown(https, http netproxy.Decision) string {
	switch {
	case https.Kind == netproxy.DecisionProxied:
		return https.Proxy
	case http.Kind == netproxy.DecisionProxied:
		return http.Proxy
	default:
		return ""
	}
}

// proxyConfigured reads, from the Proxy row already produced, whether a proxy
// applies to the target and which one to show. It never reads a Summary.
func proxyConfigured(prior *Results) (display string, ok bool) {
	if prior == nil {
		return "", false
	}
	c, found := prior.Get(CheckProxy)
	if !found || c.Proxy == "" {
		return "", false
	}
	return c.Proxy, true
}

// describeDecision is the fact value for one scheme. It names the variable, never
// its value: an invalid value is whatever the user typed, and may hold a secret.
func describeDecision(d netproxy.Decision) string {
	switch d.Kind {
	case netproxy.DecisionProxied:
		return d.Proxy + " (" + d.Variable + ")"
	case netproxy.DecisionExcluded:
		return "excluded by NO_PROXY"
	case netproxy.DecisionLoopback:
		return "not used for a loopback target"
	case netproxy.DecisionInvalid:
		return "invalid value in " + d.Variable
	default:
		return "none"
	}
}

func invalidSummary(https, http netproxy.Decision) string {
	switch {
	case https.Kind == netproxy.DecisionInvalid && http.Kind == netproxy.DecisionInvalid:
		return "Invalid " + https.Variable + " and " + http.Variable + " values"
	case https.Kind == netproxy.DecisionInvalid:
		return "Invalid " + https.Variable + " value"
	default:
		return "Invalid " + http.Variable + " value"
	}
}

// proxiedSummary names the proxy, or the two when the schemes differ, and the
// one scheme it covers when only one does.
func proxiedSummary(https, http netproxy.Decision) string {
	hs := https.Kind == netproxy.DecisionProxied
	ps := http.Kind == netproxy.DecisionProxied
	switch {
	case hs && ps && https.Proxy == http.Proxy:
		return https.Proxy
	case hs && ps:
		return https.Proxy + " (https), " + http.Proxy + " (http)"
	case hs:
		return https.Proxy + " (https only)"
	default:
		return http.Proxy + " (http only)"
	}
}
package netproxy

import (
	"net"
	"net/netip"
	"net/url"
	"os"
	"regexp"
	"strings"
	"unicode"
	"unicode/utf8"
)

// DecisionKind says what the proxy environment variables mean for one URL.
type DecisionKind int

const (
	// DecisionNone: no variable is set for this URL's scheme. It is the zero
	// value, so an unfilled Decision reads as "no proxy".
	DecisionNone DecisionKind = iota
	// DecisionProxied: a proxy carries this URL.
	DecisionProxied
	// DecisionExcluded: a valid variable is set and NO_PROXY names the target.
	DecisionExcluded
	// DecisionLoopback: a valid variable is set, but Go never proxies
	// localhost or a loopback address.
	DecisionLoopback
	// DecisionInvalid: the variable is set and is not a usable proxy URL.
	DecisionInvalid
)

// Decision is what Describe found out about one URL. It carries no credential:
// Proxy is Display's output and an invalid value is named by its variable only.
type Decision struct {
	Kind DecisionKind
	// Variable is the name of the variable read for the URL's scheme, with the
	// case it was read in (HTTPS_PROXY or https_proxy); empty for None.
	Variable string
	// Proxy is Display(proxy) when Kind is DecisionProxied, empty otherwise.
	Proxy string
}

// Describe reports which proxy, if any, applies to u in the process
// environment. The answer comes from FromEnvironment, the function every
// DevDesk client uses; only the variable's name and validity are read here.
func Describe(u *url.URL) Decision {
	return describe(u, os.Getenv, FromEnvironment)
}

// describe is Describe with its inputs injected. sel is not consulted when the
// variables alone settle the answer (None, Invalid), so it may be nil then.
func describe(u *url.URL, getenv func(string) string, sel Selector) Decision {
	var names [2]string
	switch strings.ToLower(u.Scheme) {
	case "https":
		names = [2]string{"HTTPS_PROXY", "https_proxy"}
	case "http":
		names = [2]string{"HTTP_PROXY", "http_proxy"}
	default:
		return Decision{}
	}
	// The first non-empty name wins, like Go's getEnvAny.
	name, value := "", ""
	for _, n := range names {
		if v := getenv(n); v != "" {
			name, value = n, v
			break
		}
	}
	if name == "" {
		return Decision{}
	}
	if !usableProxyValue(value) {
		return Decision{Kind: DecisionInvalid, Variable: name}
	}
	proxy, err := sel(u)
	if err != nil {
		// The error text can quote the proxy URL, credentials included.
		return Decision{Kind: DecisionInvalid, Variable: name}
	}
	if proxy != nil {
		return Decision{Kind: DecisionProxied, Variable: name, Proxy: Display(proxy)}
	}
	// A nil proxy with a valid variable: Go skips a loopback target whatever
	// NO_PROXY says, otherwise NO_PROXY named it.
	if isLoopbackHost(u.Hostname()) {
		return Decision{Kind: DecisionLoopback, Variable: name}
	}
	return Decision{Kind: DecisionExcluded, Variable: name}
}

// explicitScheme matches a value that starts with a URL scheme, as opposed to
// one that only has "://" somewhere in its path or query.
var explicitScheme = regexp.MustCompile(`^[A-Za-z][A-Za-z0-9+.-]*://`)

// usableProxyValue follows Go's parseProxy (url.Parse, then a retry with
// "http://" in front for a value without a scheme) and is stricter on three
// points, because Go ignores an unusable value and FromEnvironment alone
// cannot tell it from "no proxy":
//   - the host must not be empty;
//   - a value holding "@" must end up with userinfo, otherwise the credential
//     was mangled (an unescaped "/", "?" or "#" before the "@") and the text
//     before it became the host;
//   - the host must be printable UTF-8, since it ends up on screen.
func usableProxyValue(value string) bool {
	explicit := explicitScheme.MatchString(value)
	u, err := url.Parse(value)
	switch {
	case err != nil && explicit:
		return false
	case err == nil && u.Scheme != "" && u.Host != "":
		// Parsed as written.
	case err == nil && explicit:
		// An explicit scheme with no host, such as "http://".
		return false
	default:
		u, err = url.Parse("http://" + value)
		if err != nil {
			return false
		}
	}
	if u.Host == "" || (u.User == nil && strings.Contains(value, "@")) {
		return false
	}
	return isPrintable(u.Host)
}

// isPrintable reports whether s is valid UTF-8 made of printable runes only.
func isPrintable(s string) bool {
	if !utf8.ValidString(s) {
		return false
	}
	for _, r := range s {
		if !unicode.IsPrint(r) {
			return false
		}
	}
	return true
}

// isLoopbackHost reports whether host is localhost or a loopback address.
func isLoopbackHost(host string) bool {
	if strings.EqualFold(host, "localhost") {
		return true
	}
	addr, err := netip.ParseAddr(host)
	return err == nil && addr.Unmap().IsLoopback()
}

// defaultPorts are the ports Display shows when the URL names none.
var defaultPorts = map[string]string{
	"http":    "80",
	"https":   "443",
	"socks5":  "1080",
	"socks5h": "1080",
}

// Display renders a proxy URL as scheme://host:port and nothing else: never
// userinfo, path, query, fragment or IPv6 zone. It is the only way a proxy leaves this
// package for the screen. A scheme with no known default port shows no port
// unless the URL names one. Display(nil) is empty.
func Display(proxy *url.URL) string {
	if proxy == nil {
		return ""
	}
	port := proxy.Port()
	if port == "" {
		port = defaultPorts[strings.ToLower(proxy.Scheme)]
	}
	// The zone of a link-local address can be any text: drop it.
	host, _, _ := strings.Cut(proxy.Hostname(), "%")
	if port != "" {
		host = net.JoinHostPort(host, port)
	} else if strings.Contains(host, ":") {
		host = "[" + host + "]"
	}
	return proxy.Scheme + "://" + host
}
